import os
import sys
import logging
from pathlib import Path
from typing import Tuple, List, Optional, Dict, Any
import pandas as pd

from config import get_processed_dir, get_project_root

logger = logging.getLogger(__name__)

def load_processed_features() -> pd.DataFrame:
    """Load the processed features CSV generated by T018."""
    processed_dir = get_processed_dir()
    file_path = processed_dir / "electrolyte_features.csv"
    
    if not file_path.exists():
        raise FileNotFoundError(
            f"Processed features file not found at {file_path}. "
            "Ensure T018 (split_data) has been run successfully."
        )
    
    logger.info(f"Loading processed features from {file_path}")
    return pd.read_csv(file_path)

def assign_bins(df: pd.DataFrame) -> pd.DataFrame:
    """
    Assign 'Low' and 'High' voltage bins based on potential.
    
    Logic:
    - 'Low': potential < 4.0 (covers 0V and 2V data points)
    - 'High': potential == 4.0 (mapped from spec's 3-5V range due to data constraints)
    
    This explicitly addresses the deviation noted in the task description.
    
    Args:
        df: DataFrame containing at least a 'potential' column.
        
    Returns:
        DataFrame with an added 'bin' column containing 'Low' or 'High'.
    """
    if 'potential' not in df.columns:
        raise ValueError("Input DataFrame must contain a 'potential' column.")
    
    logger.info("Assigning voltage bins (Low: <4V, High: 4V)")
    
    # Explicit mapping: 4V is the only available high-voltage point.
    # All other potentials (0V, 2V) are considered 'Low'.
    df = df.copy()
    df['bin'] = df['potential'].apply(
        lambda x: 'High' if x >= 4.0 else 'Low'
    )
    
    bin_counts = df['bin'].value_counts()
    logger.info(f"Bin distribution: {bin_counts.to_dict()}")
    
    if bin_counts.get('High', 0) == 0:
        logger.warning("No 'High' voltage data points found in the dataset.")
    if bin_counts.get('Low', 0) == 0:
        logger.warning("No 'Low' voltage data points found in the dataset.")
        
    return df

def save_bins(df: pd.DataFrame) -> Path:
    """
    Save the bin assignments to data/processed/bins.csv.
    
    Args:
        df: DataFrame with the 'bin' column added.
        
    Returns:
        Path to the saved file.
    """
    processed_dir = get_processed_dir()
    output_path = processed_dir / "bins.csv"
    
    # Ensure directory exists
    processed_dir.mkdir(parents=True, exist_ok=True)
    
    logger.info(f"Saving bin assignments to {output_path}")
    df.to_csv(output_path, index=False)
    
    return output_path

def run_binning_pipeline() -> Path:
    """
    Execute the full binning pipeline:
    1. Load processed features.
    2. Assign bins based on potential.
    3. Save the result to data/processed/bins.csv.
    
    Returns:
        Path to the output CSV file.
    """
    logger.info("Starting binning pipeline (T019)")
    
    # 1. Load
    df = load_processed_features()
    
    # 2. Assign
    df_binned = assign_bins(df)
    
    # 3. Save
    output_path = save_bins(df_binned)
    
    logger.info(f"Binning pipeline complete. Output saved to {output_path}")
    return output_path

if __name__ == "__main__":
    # Configure basic logging for script execution
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s'
    )
    run_binning_pipeline()
